('alict_02624', 8, 'Web Development', 'What will be the result if the following CSS rule is applied to an element?', '["10px margin on all sides", "10px 20px 15px 0px left", "10px 20px right & 15px bottom", "10px top & 20px right & left", "Invalid CSS requires 4 values"]'::jsonb, 3, 'Correct answer: "10px 20px right & 15px bottom". This follows from standard HTML/CSS behaviour for the tag or property in question.', NULL, NULL, 'medium', 'Web Development', NULL, 2624, 'A/L Past Paper Series'),
